    tree.getRoot().cut(TestLine.Y_AXIS).getPlus().cut(new TestLine(new TestPoint2D(0, 0), new TestPoint2D(1, 1))).getPlus().cut(new TestLine(new TestPoint2D(1.5, 1.5), new TestPoint2D(2, 1)));
