    Assertions.assertSame(xAxisSeg, root.trim(xAxisSeg));
    Assertions.assertSame(shortSeg, root.trim(shortSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(0, Double.POSITIVE_INFINITY, TestLine.X_AXIS), (TestLineSegment) plus.trim(xAxisSeg));
    Assertions.assertSame(shortSeg, plus.trim(shortSeg));
    Assertions.assertNull(plusMinus.trim(xAxisSeg));
    Assertions.assertNull(plusMinus.trim(shortSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(0, 3, TestLine.X_AXIS), (TestLineSegment) plusPlusPlus.trim(xAxisSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(new TestPoint2D(2, 0), new TestPoint2D(2, 1)), (TestLineSegment) plusPlusPlus.trim(shortSeg));
}

