    xorChecker(AbstractRegionBSPTreeBooleanTest::emptyTree, AbstractRegionBSPTreeBooleanTest::xAxisTree).full(false).empty(false).inside(new TestPoint2D(0, 1)).outside(new TestPoint2D(0, -1)).boundary(TestPoint2D.ZERO).count(3).check();
    xorChecker(AbstractRegionBSPTreeBooleanTest::yAxisTree, AbstractRegionBSPTreeBooleanTest::fullTree).full(false).empty(false).inside(new TestPoint2D(1, 1), new TestPoint2D(1, -1)).outside(new TestPoint2D(-1, 1), new TestPoint2D(-1, -1)).boundary(new TestPoint2D(0, 1), new TestPoint2D(0, -1)).count(3).check();
    xorChecker(AbstractRegionBSPTreeBooleanTest::fullTree, AbstractRegionBSPTreeBooleanTest::yAxisTree).full(false).empty(false).inside(new TestPoint2D(1, 1), new TestPoint2D(1, -1)).outside(new TestPoint2D(-1, 1), new TestPoint2D(-1, -1)).boundary(new TestPoint2D(0, 1), new TestPoint2D(0, -1)).count(3).check();
    xorChecker(AbstractRegionBSPTreeBooleanTest::xAxisTree, AbstractRegionBSPTreeBooleanTest::yAxisTree).full(false).empty(false).inside(new TestPoint2D(1, 1), new TestPoint2D(-1, -1)).outside(new TestPoint2D(-1, 1), new TestPoint2D(1, -1)).boundary(TestPoint2D.ZERO).count(7).check(t -> {
        final TestLineSegment minusSeg = (TestLineSegment) t.getRoot().getMinus().getCut();
        PartitionTestUtils.assertPointsEqual(TestPoint2D.ZERO, minusSeg.getStartPoint());
        PartitionTestUtils.assertPointsEqual(new TestPoint2D(0.0, Double.POSITIVE_INFINITY), minusSeg.getEndPoint());
        final TestLineSegment plusSeg = (TestLineSegment) t.getRoot().getPlus().getCut();
        PartitionTestUtils.assertPointsEqual(new TestPoint2D(0.0, Double.NEGATIVE_INFINITY), plusSeg.getStartPoint());
        PartitionTestUtils.assertPointsEqual(TestPoint2D.ZERO, plusSeg.getEndPoint());
    });
}

