@Test
void testOf_hyperplanes() {
    // act/assert
    Assertions.assertSame(Interval.full(), Interval.of(null, null));
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(1, true, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(1, false, TEST_PRECISION)), 1, 1);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(1, false, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(1, true, TEST_PRECISION)), 1, 1);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(-2, false, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(5, true, TEST_PRECISION)), -2, 5);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(5, true, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(-2, false, TEST_PRECISION)), -2, 5);
    checkInterval(Interval.of(null, OrientedPoints.fromLocationAndDirection(5, true, TEST_PRECISION)), Double.NEGATIVE_INFINITY, 5);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(5, true, TEST_PRECISION), null), Double.NEGATIVE_INFINITY, 5);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(Double.NEGATIVE_INFINITY, false, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(5, true, TEST_PRECISION)), Double.NEGATIVE_INFINITY, 5);
    checkInterval(Interval.of(null, OrientedPoints.fromLocationAndDirection(5, false, TEST_PRECISION)), 5, Double.POSITIVE_INFINITY);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(5, false, TEST_PRECISION), null), 5, Double.POSITIVE_INFINITY);
    checkInterval(Interval.of(OrientedPoints.fromLocationAndDirection(Double.POSITIVE_INFINITY, true, TEST_PRECISION), OrientedPoints.fromLocationAndDirection(5, false, TEST_PRECISION)), 5, Double.POSITIVE_INFINITY);
}

