    final int testCnt = 5;
    final int pointCnt = 1_000;
    final double range = 1e10;
    final List<Vector1D> pts = new ArrayList<>();
    for (int i = 0; i < pointCnt; ++i) {
        final Vector1D pt = randomPoint(rnd, range);
        pts.add(pt);
