    final Bounds3D b4 = Bounds3D.from(Vector3D.of(1.001, 1.001, 1.001), Vector3D.of(2.001, 2.001, 2.001));
    // act/assert
    Assertions.assertTrue(b1.eq(b1, low));
    Assertions.assertFalse(b1.eq(b2, low));
