@Test
void testLinecast_nonSpan() {
    // -- arrange
    final Vector3D min = Vector3D.ZERO;
    final Vector3D max = Vector3D.of(1, 1, 1);
    final Bounds3D bounds = Bounds3D.from(min, max);
    final Vector3D centroid = bounds.getCentroid();
    final Vector3D start = Vector3D.of(max.getX(), centroid.getY(), centroid.getZ());
    final Vector3D end = Vector3D.of(min.getX(), centroid.getY(), centroid.getZ());
    final Line3D line = Lines3D.fromPoints(start, end, TEST_PRECISION);
    // -- act/assert
    linecastChecker(bounds).expect(end, Vector3D.Unit.MINUS_X).whenGiven(line.rayFrom(-0.5));
    linecastChecker(bounds).expect(start, Vector3D.Unit.PLUS_X).whenGiven(line.reverseRayTo(-0.5));
    linecastChecker(bounds).expectNothing().whenGiven(line.segment(-0.9, -0.1));
    linecastChecker(bounds).expect(end, Vector3D.Unit.MINUS_X).whenGiven(line.segment(-0.9, 0.1));
    linecastChecker(bounds).expect(start, Vector3D.Unit.PLUS_X).whenGiven(line.segment(-1.1, -0.1));
    linecastChecker(bounds).expect(start, Vector3D.Unit.PLUS_X).expect(end, Vector3D.Unit.MINUS_X).whenGiven(line.segment(-1.1, 0.1));
}

