@Test
void testGetEmbedding() {
    // arrange
    final Vector3D pt = Vector3D.of(1, 2, 3);
    EuclideanTestUtils.permuteSkipZero(-4, 4, 1, (x, y, z) -> {
        final Plane plane = Planes.fromPointAndNormal(pt, Vector3D.of(x, y, z), TEST_PRECISION);
