            assertRadiansEquals(0.0, resultSeq.getAngle3());
            checkQuaternion(resultQuat, inputQuat.getQuaternion().getW(), inputQuat.getQuaternion().getX(), inputQuat.getQuaternion().getY(), inputQuat.getQuaternion().getZ());
        }
    }
}

