    final Vector2D min = Vector2D.ZERO;
    final Vector2D max = Vector2D.of(1, 1);
    final Vector2D insideMin = Vector2D.of(0.1, 0.1);
    final Vector2D insideMax = Vector2D.of(0.9, 0.9);
