@Test
void testConvexPolygonFromPath_invalidPaths() {
    // arrange
    final Pattern unclosedPattern = Pattern.compile("Cannot construct convex polygon from unclosed path.*");
    final Pattern notEnoughElementsPattern = Pattern.compile("Cannot construct convex polygon from path with less than 3 elements.*");
    final Pattern nonConvexPattern = Pattern.compile("Cannot construct convex polygon from non-convex path.*");
    // act/assert
    GeometryTestUtils.assertThrowsWithMessage(() -> {
        ConvexArea.convexPolygonFromPath(LinePath.empty());
    }, IllegalArgumentException.class, unclosedPattern);
    GeometryTestUtils.assertThrowsWithMessage(() -> {
        ConvexArea.convexPolygonFromPath(LinePath.fromVertices(Arrays.asList(Vector2D.ZERO, Vector2D.Unit.PLUS_X), TEST_PRECISION));
    }, IllegalArgumentException.class, unclosedPattern);
    GeometryTestUtils.assertThrowsWithMessage(() -> {
        ConvexArea.convexPolygonFromPath(LinePath.fromVertices(Arrays.asList(Vector2D.ZERO, Vector2D.Unit.PLUS_X, Vector2D.ZERO), TEST_PRECISION));
    }, IllegalArgumentException.class, notEnoughElementsPattern);
    GeometryTestUtils.assertThrowsWithMessage(() -> {
        ConvexArea.convexPolygonFromPath(LinePath.fromVertexLoop(Arrays.asList(Vector2D.ZERO, Vector2D.Unit.PLUS_Y, Vector2D.of(1, 1), Vector2D.Unit.PLUS_X), TEST_PRECISION));
    }, IllegalArgumentException.class, nonConvexPattern);
}

