@Test
void testSplit() {
    // --- arrange
    final Vector2D p0 = Vector2D.of(1, 1);
    final Vector2D p1 = Vector2D.of(-3, 1);
    final Vector2D high = Vector2D.of(2, 1);
    final Vector2D delta = Vector2D.of(1e-11, 1e-11);
    final ReverseRay revRay = Lines.reverseRayFromPointAndDirection(p0, Vector2D.Unit.PLUS_X, TEST_PRECISION);
    // --- act
    // parallel
    checkSplit(revRay.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), 0, TEST_PRECISION)), null, null, null, p0);
    checkSplit(revRay.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), Math.PI, TEST_PRECISION)), null, p0, null, null);
    // coincident
    checkSplit(revRay.split(Lines.fromPointAndAngle(p0.add(delta), 1e-20, TEST_PRECISION)), null, null, null, null);
    // through point on revRay
    checkSplit(revRay.split(Lines.fromPointAndAngle(p1, 1, TEST_PRECISION)), null, p1, p1, p0);
    checkSplit(revRay.split(Lines.fromPointAndAngle(p1, -1, TEST_PRECISION)), p1, p0, null, p1);
    // through end point
    checkSplit(revRay.split(Lines.fromPointAndAngle(p0.subtract(delta), 1, TEST_PRECISION)), null, p0, null, null);
    checkSplit(revRay.split(Lines.fromPointAndAngle(p0.add(delta), -1, TEST_PRECISION)), null, null, null, p0);
    // intersection above end point
    checkSplit(revRay.split(Lines.fromPointAndAngle(high, 1, TEST_PRECISION)), null, p0, null, null);
    checkSplit(revRay.split(Lines.fromPointAndAngle(high, -1, TEST_PRECISION)), null, null, null, p0);
}

