@Test
void testSplit() {
    // --- arrange
    final Vector2D p0 = Vector2D.of(1, 1);
    final Vector2D p1 = Vector2D.of(3, 1);
    final Vector2D mid = p0.lerp(p1, 0.5);
    final Vector2D low = Vector2D.of(0, 1);
    final Vector2D high = Vector2D.of(3, 1);
    final Vector2D delta = Vector2D.of(1e-11, 1e-11);
    final Segment seg = Lines.segmentFromPoints(Vector2D.of(1, 1), Vector2D.of(3, 1), TEST_PRECISION);
    // --- act
    // parallel
    checkSplit(seg.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), 0, TEST_PRECISION)), null, null, p0, p1);
    checkSplit(seg.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), Math.PI, TEST_PRECISION)), p0, p1, null, null);
    // coincident
    checkSplit(seg.split(Lines.fromPointAndAngle(p0.add(delta), 1e-20, TEST_PRECISION)), null, null, null, null);
    // through mid point
    checkSplit(seg.split(Lines.fromPointAndAngle(mid, 1, TEST_PRECISION)), p0, mid, mid, p1);
    checkSplit(seg.split(Lines.fromPointAndAngle(mid, -1, TEST_PRECISION)), mid, p1, p0, mid);
    // through start point
    checkSplit(seg.split(Lines.fromPointAndAngle(p0.subtract(delta), 1, TEST_PRECISION)), null, null, p0, p1);
    checkSplit(seg.split(Lines.fromPointAndAngle(p0.add(delta), -1, TEST_PRECISION)), p0, p1, null, null);
    // through end point
    checkSplit(seg.split(Lines.fromPointAndAngle(p1.subtract(delta), 1, TEST_PRECISION)), p0, p1, null, null);
    checkSplit(seg.split(Lines.fromPointAndAngle(p1.add(delta), -1, TEST_PRECISION)), null, null, p0, p1);
    // intersection below minus
    checkSplit(seg.split(Lines.fromPointAndAngle(low, 1, TEST_PRECISION)), null, null, p0, p1);
    checkSplit(seg.split(Lines.fromPointAndAngle(low, -1, TEST_PRECISION)), p0, p1, null, null);
    // intersection above minus
    checkSplit(seg.split(Lines.fromPointAndAngle(high, 1, TEST_PRECISION)), p0, p1, null, null);
    checkSplit(seg.split(Lines.fromPointAndAngle(high, -1, TEST_PRECISION)), null, null, p0, p1);
}

