@Test
void testIntersections() {
    // --- arrange
    final Circle c = Circle.from(Vector2D.of(2, 1), 2, TEST_PRECISION);
    final double sqrt3 = Math.sqrt(3);
    // --- act/assert
    // descending horizontal lines
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, 4), Vector2D.of(5, 4), TEST_PRECISION));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, 3), Vector2D.of(5, 3), TEST_PRECISION), Vector2D.of(2, 3));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, 2), Vector2D.of(5, 2), TEST_PRECISION), Vector2D.of(2 - sqrt3, 2), Vector2D.of(2 + sqrt3, 2));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, 1), Vector2D.of(5, 1), TEST_PRECISION), Vector2D.of(0, 1), Vector2D.of(4, 1));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, 0), Vector2D.of(5, 0), TEST_PRECISION), Vector2D.of(2 - sqrt3, 0), Vector2D.of(2 + sqrt3, 0));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, -1), Vector2D.of(5, -1), TEST_PRECISION), Vector2D.of(2, -1));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, -2), Vector2D.of(5, -2), TEST_PRECISION));
    // ascending vertical lines
    checkIntersections(c, Lines.fromPoints(Vector2D.of(-1, -2), Vector2D.of(-1, 5), TEST_PRECISION));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(0, -2), Vector2D.of(0, 5), TEST_PRECISION), Vector2D.of(0, 1));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(1, -2), Vector2D.of(1, 5), TEST_PRECISION), Vector2D.of(1, 1 - sqrt3), Vector2D.of(1, 1 + sqrt3));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(2, -2), Vector2D.of(2, 5), TEST_PRECISION), Vector2D.of(2, -1), Vector2D.of(2, 3));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(3, -2), Vector2D.of(3, 5), TEST_PRECISION), Vector2D.of(3, 1 - sqrt3), Vector2D.of(3, 1 + sqrt3));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(4, -2), Vector2D.of(4, 5), TEST_PRECISION), Vector2D.of(4, 1));
    checkIntersections(c, Lines.fromPoints(Vector2D.of(5, -2), Vector2D.of(5, 5), TEST_PRECISION));
    // diagonal from origin
    final Vector2D center = c.getCenter();
    checkIntersections(c, Lines.fromPoints(Vector2D.ZERO, c.getCenter(), TEST_PRECISION), center.withNorm(center.norm() - c.getRadius()), center.withNorm(center.norm() + c.getRadius()));
}

