    final TriangleMesh.Face face2 = mesh.getFace(1);
    EuclideanTestUtils.assertVertexLoopSequence(Arrays.asList(Vector3D.ZERO, Vector3D.of(0, 1, 0), Vector3D.of(0.5, 0, 0)), face2.getVertices(), TEST_PRECISION);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.Unit.MINUS_Z, face2.getPolygon().getPlane().getNormal(), TEST_EPS);
