    }
    // act
    final PointMap<Point2S, Integer> map = getMap(PRECISION);
    final PointMapChecker<Point2S, Integer> checker = checkerFor(map);
    for (int i = 0; i < cnt; ++i) {
        final Point2S key = pts.get(i);
        map.put(key, i);
        checker.expectEntry(key, i);
    }
    // assert
    checker.check();
}

