@Test
void testProject() {
    // arrange
    final RegionBSPTree2S tree = RegionBSPTree2S.empty();
    tree.insert(EQUATOR.arc(0, Math.PI));
    tree.insert(X_MERIDIAN.arc(Math.PI, 0));
    // act/assert
    SphericalTestUtils.assertPointsEq(Point2S.of(Angle.PI_OVER_TWO, Angle.PI_OVER_TWO), tree.project(Point2S.of(Angle.PI_OVER_TWO, Angle.PI_OVER_TWO + 0.2)), TEST_EPS);
    SphericalTestUtils.assertPointsEq(Point2S.PLUS_K, tree.project(Point2S.of(-Angle.PI_OVER_TWO, 0.2)), TEST_EPS);
    SphericalTestUtils.assertPointsEq(Point2S.PLUS_I, tree.project(Point2S.of(-0.5, Angle.PI_OVER_TWO)), TEST_EPS);
    SphericalTestUtils.assertPointsEq(Point2S.MINUS_I, tree.project(Point2S.of(Math.PI + 0.5, Angle.PI_OVER_TWO)), TEST_EPS);
    final Point2S centroid = tree.getCentroid();
    SphericalTestUtils.assertPointsEq(Point2S.PLUS_K, tree.project(centroid.slerp(Point2S.PLUS_K, 1e-10)), TEST_EPS);
    SphericalTestUtils.assertPointsEq(Point2S.PLUS_J, tree.project(centroid.slerp(Point2S.PLUS_J, 1e-10)), TEST_EPS);
}

